from typing import Optional

from pyvkteamsclient.client.base.client import BaseClient
from pyvkteamsclient.client.decorators import api_version_check
from pyvkteamsclient.tracer import tracer


class PushNotificationsMethods(BaseClient):
    """
    Методы группы 'Пуш-уведомления' из https://im-docs.corp.mail.ru/
    """

    @api_version_check(min_version=60)
    @tracer.start_as_current_span("push.rapi_invalidatePushToken")
    def rapi_invalidatePushToken(
        self,
        sn: str,
        sid: str,
        push_token: Optional[str] = None,
        voip_push_token: Optional[str] = None,
    ):
        """
        Инвалидировать пуш-токен

        Метод используется для уведомления сервера о
        необходимости перестать слать пуш-уведомления
        с выбранным токеном (необходимо передать как минимум
        один из параметров pushToken или voipPushToken).

        Метод может быть использован при компрометации пуш-токена
        или истечении срока его действия.

        По соображениям безопасности вместо идентификатора сессии
        метод принимает его MD5 хэш-сумму.

        Данная информация отправляется сервером в каждом пуше
        и позволяет инвалидировать токен любому получателю пуш-уведомления.
        :param sn: Уникальный идентификатор пользователя внутри сервиса
        :param sid: MD5 хэш-сумма от идентификатора сессии пользователя, которой принадлежит пуш-токен
        :param pushToken: Android или iOS пуш-токен для инвалидации
        :param voipPushToken: iOS voip-пуш-токен для инвалидации
        :return: тело ответа сервера
        """
        return self.post(
            "rapi/invalidatePushToken",
            headers={"Content-Type": "application/json"},
            json={
                "reqId": "testReqId-1532345345",
                "params": {
                    "sn": sn,
                    "sid": sid,
                    "pushToken": push_token,
                    "voipPushToken": voip_push_token,
                },
            },
        )
